// «Договоры в PDF» cards in the real chat, from data the feature computes on PDFs generated by the test:
//  - the contract card: the page strip (text / unread scan, marks where terms are), the deadlines on an axis with
//    «Напомнить» only for future dates (the cross-app kind `reminder` runs with the date and text), every term with its
//    verbatim quote, page and clause, «Показать на странице» with the quoted line marked (ipc `page`), the one-line
//    disclaimer; safe text from file names and contract text;
//  - the comparison card: the clause map, the changed terms table, word diffs (del / ins), «Поменять местами» (ipc).
process.env.PETYA_SMOKE_TEST='1';
const assert=require('node:assert/strict');
const fs=require('node:fs'),os=require('node:os'),path=require('node:path');
require.cache[require.resolve('./smoke.cjs')]={exports:async win=>{
 const js=code=>win.webContents.executeJavaScript(code).catch(e=>{throw Error('Page script failed: '+code.slice(0,160)+' — '+e.message);});
 const until=async(code,ms=8000)=>{for(let i=0;i<ms/40;i++){if(await js(code))return true;await new Promise(r=>setTimeout(r,40));}return false;};
 await js('window.chatNavigationReady');
 const M=require('./fixtures/pdf-contracts/make-pdf.cjs'),{V1,V2}=require('./fixtures/pdf-contracts/contract.cjs');
 const app=require('../src/extensions/pdf-contracts/feature.cjs');
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'petya-contracts-ui-'));
 const v1=path.join(dir,'Договор <img src=x onerror=alert(1)> v1.pdf'),v2=path.join(dir,'Договор v2.pdf');
 fs.writeFileSync(v1,M.make(M.contract(V1,{perPage:30})));fs.writeFileSync(v2,M.make([...M.contract(V2,{perPage:30}),{scan:true}]));
 app.deps.now=()=>Date.parse('2026-11-09T09:00:00Z');app.deps.ocr={find:()=>null,recognize:async()=>[]};
 const topic={id:'t',title:'Чат',messages:[]};const pending=new Map([['a',{id:'a',name:path.basename(v1),localSourcePath:v1}]]);
 const s={settings:{'extension_pdf-contracts':'true'},dataRoot:path.join(dir,'company'),requestProgress:{report(){}},
  attachments:{pending,list:()=>[...pending.values()].map(x=>({id:x.id,name:x.name})),take:ids=>ids.map(id=>pending.get(id)),info:x=>({id:x.id,name:x.name}),remove:id=>pending.delete(id)},
  dialogue:{state:{topics:[topic],projects:[],activeProjectId:'general'},active:()=>topic,persist(){},rememberAction(c,text){topic.messages.push({role:'user',text:c},{role:'assistant',text});}}};
 await app.turn(s,'разбери этот договор');
 const analyzed=topic.messages.at(-1).extensionData.contractCard;
 pending.set('b',{id:'b',name:'Договор v2.pdf',localSourcePath:v2});
 await app.turn(s,'сравни с прошлой версией договора');
 const compared=topic.messages.at(-1).extensionData.contractCard;
 const {ipc}=app.setup(s);
 const {ipcMain}=require('electron'),calls=[];
 ipcMain.removeHandler('petya:feature');
 ipcMain.handle('petya:feature',async(event,name,method,...args)=>{
  calls.push([name,method,...args]);
  if(name==='appLinks'&&method==='available')return args[0]==='reminder'?[{id:'reminders',name:'Напоминания',label:'Напомнить'}]:[];
  if(name==='appLinks'&&method==='run')return require('../src/extensions/reminders/reminder-link.cjs').run({},args[2]).then(r=>({text:r.ask}));
  if(name==='pdfContracts'&&method==='page')return ipc.page(...args);
  if(name==='pdfContracts'&&method==='swap')return ipc.swap(...args);
  return null;
 });
 await js(`view('home');showDialogueMessages([{role:'user',text:'разбери этот договор'},{role:'assistant',text:'Договор.',by:'Договоры в PDF',extensionData:{contractCard:${JSON.stringify(analyzed)}}},{role:'user',text:'сравни с прошлой версией договора'},{role:'assistant',text:'Сравнил.',by:'Договоры в PDF',extensionData:{contractCard:${JSON.stringify(compared)}}}],'Договор')`);
 assert.ok(await until("document.querySelectorAll('.contract-card').length===2"),'two cards');
 const A="document.querySelector('.contract-card[data-mode=analyze]')",B="document.querySelector('.contract-card[data-mode=compare]')";
 assert.equal(await js(A+".querySelectorAll('img').length"),0,'file names are text');
 assert.match(await js(A+".querySelector('.kit-key').textContent"),/<img/);
 assert.equal(await js(A+".querySelectorAll('.pc-page').length"),2);
 assert.ok(await js(A+".querySelector('.pc-page[data-page=\"1\"] .pc-page-dot')!==null"),'terms marked on page 1');
 assert.equal(await js(A+".querySelectorAll('.pc-deadline').length"),4);
 assert.equal(await js(A+".querySelectorAll('.pc-deadline.past').length"),1,'the advance date has passed');
 assert.ok(await until(A+".querySelectorAll('.pc-deadline .kit-links[data-kind=reminder] button').length===3"),'«Напомнить» for the three future dates');
 assert.equal(await js(A+".querySelectorAll('.pc-group').length"),9);
 assert.equal(await js(A+".querySelector('.pc-group[data-kind=penalty] .pc-quote').textContent.startsWith('За нарушение сроков выполнения работ Исполнитель уплачивает Заказчику неустойку')"),true);
 assert.equal(await js(A+".querySelectorAll('.pc-disclaimer').length"),1,'the disclaimer once');
 assert.equal(await js("document.querySelectorAll('.contract-card .pc-disclaimer').length"),2);
 // «Показать на странице»: the page text with the quoted lines marked.
 await js(A+".querySelector('.pc-group[data-kind=term] .pc-show').click()");
 assert.ok(await until(A+".querySelector('.pc-pageview .pc-line.hit')!==null"),'page view');
 assert.match(await js(A+".querySelector('.pc-pageview .pc-line.hit').textContent"),/^5\.1\. Договор вступает в силу/);
 await require('./card-shot.cjs')(win,'.contract-card[data-mode=analyze]','petya-pdf-contracts',{width:700});
 // The terms further down the card.
 await js("(()=>{const b=document.querySelector('#card-shot');b.scrollTop=b.scrollHeight;})()");await new Promise(r=>setTimeout(r,300));
 fs.writeFileSync(path.join(os.tmpdir(),'petya-pdf-contracts-terms.png'),(await win.webContents.capturePage()).toPNG());
 await js("(()=>{const b=document.getElementById('card-shot');const home=document.querySelector('.message-content')?.parentNode||document.body;for(const c of b.querySelectorAll('.contract-card'))home.append(c);b.remove();})()");
 // «Напомнить»: the reminder request with the date and what it is.
 await js(A+".querySelector('.pc-deadline[data-date=\"2026-12-01\"] .kit-links button').click()");
 assert.ok(await until("JSON.stringify("+JSON.stringify([])+")!==null")&&await (async()=>{for(let i=0;i<100&&!calls.some(c=>c[1]==='run');i++)await new Promise(r=>setTimeout(r,30));return true;})());
 const run=calls.find(c=>c[0]==='appLinks'&&c[1]==='run');
 assert.equal(run[2],'reminder');assert.equal(run[4].date,'2026-12-01');assert.match(run[4].text,/^договор «Договор <img src=x onerror=alert\(1\)> v1»: последний день, чтобы отказаться от продления \(стр\. 2\)$/);
 // The comparison.
 assert.equal(await js(B+".querySelectorAll('.pc-seg').length"),compared.rows.length);
 assert.equal(await js(B+".querySelectorAll('.pc-diff').length"),5);
 assert.equal(await js(B+".querySelector('.pc-diff[data-status=changed] del').textContent"),'4 800');
 assert.equal(await js(B+".querySelector('.pc-diff[data-status=changed] ins').textContent"),'5 400');
 assert.equal(await js(B+".querySelectorAll('.pc-terms tbody tr').length"),3);
 await require('./card-shot.cjs')(win,'.contract-card[data-mode=compare]','petya-pdf-contracts-diff',{width:700});
 await js("(()=>{const b=document.getElementById('card-shot');const home=document.querySelector('.message-content')?.parentNode||document.body;for(const c of b.querySelectorAll('.contract-card'))home.append(c);b.remove();})()");
 await js(B+".querySelector('.kit-actions button').click()");
 assert.ok(await until(B+"?.querySelector('.pc-diff[data-status=added] .pc-diff-num')?.textContent==='п. 1.2'"),'swapped: 1.2 is now added');
 app.deps.now=()=>Date.now();app.deps.ocr=require('../src/extensions/pdf-contracts/ocr.cjs');
 fs.rmSync(dir,{recursive:true,force:true});
 console.log('PDF contract cards: page strip, deadlines with «Напомнить» for future dates through the reminder kind, terms with verbatim quotes and pages, page view with the quote marked, disclaimer once, clause map, changed terms, word diff, swap, safe text passed');
}};
require('../src/main.cjs');
